def initial_rot():
    s=np.array(json.load(open(ROOT+'/initial/meta.json'))['proprio']['now'])
    return fk(s[3:10])[1]

def move_xyz(pos, tag, rot=None,step=.04):
    s=now()
    if rot is None: rot=initial_rot()
    B=Rotation.from_euler('z',s[2]).as_matrix()
    local=B.T@(np.array(pos)-np.r_[s[:2],0])
    q=ik(local,B.T@rot,s[3:10])
    p,R=fk(q)
    if np.linalg.norm(p-local)>.001 or np.linalg.norm(R-B.T@rot)>.01: raise RuntimeError('Unreachable target')
    return move_q(q,tag,step)

def grip(command,tag):
    A=np.zeros(11);A[10]=command
    return send([A],tag)
